from typing import List

def words_string(s: str) -> List[str]:
    """
    Splits the string into words and returns them as a list.
    """
    words = []
    current_word = ""
    in_quotes = False
    in_number = False
    in_parentheses = False

    for char in s:
        if char == "," or char == " ":
            if in_word(current_word):
                words.append(current_word)
                current_word = ""
            if char == ",":
                in_quotes = False
                in_parentheses = False
                in_number = False
        elif char == '"':
            if in_quotes:
                in_quotes = False
            else:
                in_quotes = True
        elif char == "(":
            if in_word(current_word) and not in_parentheses:
                in_parentheses = True
        elif char == ")":
            if in_word(current_word) and in_parentheses:
                in_parentheses = False
                in_quotes = False
            if in_quotes:
                in_number = False
        elif in_quotes:
            if not in_number:
                current_word += char
            elif current_word[-1].isdigit():
                current_word += char
        elif in_parentheses:
            current_word += char
        else:
            if current_word and not in_number:
                if char.isdigit():
                    in_number = True
            current_word += char

    if in_word(current_word):
        words.append(current_word)

    return words

def is_word(word):
    return word and not word.isspace()

def in_word(text):
    return text and text.isspace() or (is_word(text) and in_quotes or not in_quotes or not in_parentheses)

def in_quotes(word):
    return word and word[0] == '"' and word[-1] == '"'

def is_number(word):
    return word and word.isdigit()

def test_words_string():
    assert words_string("Hi, my name is John") == ["Hi", "my", "name", "is", "John"]
    assert words_string("One, two, three, four, five, six") == ["One", "two", "three", "four", "five", "six"]
    assert words_string("This is (a) test") == ["This", "is", "a", "test"]
    assert words_string("No (quotes) here, but (numbers) like 1234") == ["No", "quotes", "here", "but", "numbers", "like", "1234"]
    assert words_string("Numbers (in (parentheses))!") == ["Numbers", "in", "parentheses", "!"]

