def rounded_avg(n, m):
    if n > m:
        return -1

    total_sum = sum(range(n, m + 1))
    average = total_sum / (m - n + 1)
    rounded_average = round(average)

    if rounded_average < 0:
        return -1
    elif 9 < rounded_average < 12:
        rounded_average += 1

    return f"0b{bin(rounded_average)[2:]}"


