def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    n = len(arr)
    i = None

    # Find the last index that is greater than the next element
    for j in range(n - 2, -1, -1):
        if arr[j] > arr[j + 1]:
            i = j
            break

    # If no such index found, return True
    if i is None:
        return True

    # Perform right shift operations until the array is sorted
    while i < n - 1:
        arr[i + 1] = arr[i]
        i += 1

    # The array is not sorted, return False
    return arr == sorted(arr)
