def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into a list of lowercase letters
    letters = test.split()

    # Initialize an empty dictionary to store the histogram
    histogram_dict = {}

    # Iterate over each letter in the list of letters
    for letter in letters:
        # If the letter is already in the dictionary, increment its count
        if letter in histogram_dict:
            histogram_dict[letter] += 1
        # If the letter is not in the dictionary, add it with a count of 1
        else:
            histogram_dict[letter] = 1

    # Find the letter with the highest count
    max_count = max(histogram_dict.values())

    # Filter the dictionary to only include letters with the maximum count
    most_common_letters = {letter: count for letter, count in histogram_dict.items() if count == max_count}

    return most_common_letters


